        }
        if q.entered.is_none() {
            if let Some(next) = q.waiting.iter().find(|entry| entry.ready) {
                next.thread.unpark();
            }
        }
    }
}
pub fn layout()->(usize,usize){(std::mem::size_of::<AuthorityAdmission>(),std::mem::size_of::<Entry>())}
}
